58	/**
59	 * Gestione asset di un singolo record (digital-hub #16).
60	 *
61	 * Page record-scoped, full-width, fuori dalla navigazione: si raggiunge solo
62	 * dall'azione {@see \AtrioTeam\DigitalHub\Assets\Filament\Actions\ManageAssetsAction}
63	 * nella tabella di una resource. La route porta owner via coppia polimorfica
64	 * (morph alias + chiave): `/assets/{ownerType}/{owner}`, così la pagina è
65	 * generica per qualunque modello che usa il trait HasAssets, non solo Product.
66	 *
67	 * Lo stato dell'UI (folder attiva, ecc.) sarà aggiunto negli step successivi
68	 * di #16a; qui c'è solo lo scheletro navigabile.
69	 */
70	class AssetManager extends Page implements HasActions
71	{
72	    use InteractsWithActions;
73	
74	    protected static string|BackedEnum|null $navigationIcon = Heroicon::OutlinedFolderOpen;
75	
76	    protected static ?string $slug = 'assets';
77	
78	    protected string $view = 'digital-hub::filament.pages.asset-manager';
79	
80	    protected Width|string|null $maxContentWidth = Width::Full;
81	
82	    /**
83	     * Layout "base" (solo body, niente sidebar/topbar): la pagina è un editor di
84	     * asset a tutto schermo, presentato come un "finto modal" che si chiude con la
85	     * X tornando al catalogo (vedi blade). Il layout base include comunque gli
86	     * stili/script Filament e il componente notifiche, quindi toast e modali delle
87	     * action continuano a funzionare.
88	     */
89	    protected static string $layout = 'filament-panels::components.layout.base';
90	
91	    /** icona di "sposta", usata per file e cartelle */
92	    protected Heroicon $moveActionIcon = Heroicon::OutlinedArrowUpOnSquareStack;
93	
94	    /** Morph alias del record proprietario (es. `product`). */
95	    public string $ownerType;
96	
97	    /** Chiave primaria del record proprietario. */
98	    public int|string $ownerKey;
99	
100	    /** Folder attualmente selezionata; null = root ("Home") del record. */
101	    public ?int $activeFolderId = null;
102	
103	    /**
104	     * URL della lista da cui si è arrivati (catturato dal Referer alla mount),
105	     * per il link "indietro". null se assente o non locale. È public così
106	     * sopravvive alle update Livewire successive (la mount gira una sola volta).
107	     */
108	    public ?string $returnUrl = null;
109	
110	    /**
111	     * Id dei media selezionati per le azioni multiple (checkbox sulle card).
112	     * @var array<int, int|string>
113	     */
114	    public array $selectedAssetIds = [];
115	
116	    /**
117	     * Id delle sottocartelle selezionate per le azioni multiple (checkbox sulle
118	     * tile cartella). Una cartella selezionata vale come "tutti i media del suo
119	     * sottoalbero" per scarica/condividi; sposta/elimina multipli restano
120	     * solo-file (nascosti quando ci sono cartelle in selezione).
121	     * @var array<int, int|string>
122	     */
123	    public array $selectedFolderIds = [];
124	
125	    /** URL dell'ultimo share creato, mostrato nel modal "share-link" (22g). */
126	    public ?string $lastShareUrl = null;
127	
128	    /**
129	     * Filtri della griglia (14c). Quando almeno uno è attivo la vista passa in
130	     * modalità "piatta": tutti i file del record (cartelle ignorate) che
131	     * corrispondono, invece della navigazione cartella per cartella.
132	     *
133	     * `$filterType` è il nome del case {@see AssetFileType} (es. `Image`);
134	     * `$filterUploadedBy` è l'id dell'autore dell'upload; le date sono `Y-m-d`
135	     * e filtrano `created_at` (confrontata in orario locale Europe/Rome);
136	     * `$filterMinSizeMb`/`$filterMaxSizeMb` sono gli estremi (in MB) dell'intervallo
137	     * di peso (slider doppio) — attivi solo se restringono davvero (min > 0 o max
138	     * sotto il peso del file più grande); null = estremo libero.
139	     */
140	    public ?string $filterType = null;
141	
142	    public int|string|null $filterUploadedBy = null;
143	
144	    public ?string $filterUploadedFrom = null;
145	
146	    public ?string $filterUploadedTo = null;
147	
148	    public ?float $filterMinSizeMb = null;
149	
150	    public ?float $filterMaxSizeMb = null;
151	
152	    /**
153	     * Cache per-request del record risolto (privata: non serializzata da Livewire).
154	     * @var (Model&OwnsAssets)|null
155	     */
156	    private ?Model $ownerModel = null;
157	
158	    /**
159	     * Cache per-request delle folder del record (privata: non serializzata da Livewire).
160	     * @var null|EloquentCollection<int,AssetFolder>
161	     */
162	    private ?EloquentCollection $folderCache = null;
163	
164	    /**
165	     * Cache per-request del resolver ownership-scoped (privata: non serializzata
166	     * da Livewire).
167	     */
168	    private ?OwnedAssetResolver $resolverCache = null;
169	
170	    /**
171	     * Cache del builder delle preview delle tile cartella (miniature,
172	     * conteggi, stato), privata: non serializzata da Livewire.
173	     */
174	    private ?SubfolderPreviewBuilder $subfolderPreviewCache = null;
175	
176	    /**
177	     * Cache per-request di tutti i media asset del record (ogni cartella),
178	     * base sia delle opzioni dei filtri sia della vista piatta filtrata (14c).
179	     * Privata: non serializzata da Livewire.
180	     *
181	     * @var null|EloquentCollection<int, Media>
182	     */
183	    private ?EloquentCollection $recordAssetsCache = null;
184	
185	    #[Override]
186	    public static function getRoutePath(Panel $panel): string
187	    {
188	        return '/assets/{ownerType}/{owner}';
189	    }
190	
191	    public static function shouldRegisterNavigation(): bool
192	    {
193	        return false;
194	    }
195	
196	    /**
197	     * I parametri di route (ownerType, owner) sono iniettati da Livewire.
198	     */
199	    public function mount(string $ownerType, int|string $owner): void
200	    {
201	        $this->ownerType = $ownerType;
202	        $this->ownerKey = $owner;
203	
204	        // valida subito: record risolvibile e dotato del trait HasAssets
205	        $this->resolveOwner();
206	
207	        // la lista di provenienza (con i suoi filtri, es. sottocategoria) è
208	        // esattamente la pagina che ha linkato qui: la prendiamo dal Referer.
209	        // Fallback (link diretto/tab nuova, niente referer): la lista della
210	        // resource del record, senza filtri.
211	        $this->returnUrl = $this->resolveReturnUrl(request()->headers->get('referer'))
212	            ?? $this->resourceIndexUrl();
213	    }
214	
215	    /**
216	     * Valida l'URL di ritorno: accetta solo URL dello stesso host dell'app (no
217	     * open redirect verso domini esterni) e scarta l'auto-riferimento alla
218	     * pagina asset stessa (es. reload). null se non valido.
219	     */
220	    private function resolveReturnUrl(?string $url): ?string
221	    {
222	        if (! is_string($url) || $url === '') {
223	            return null;
224	        }
225	
226	        $host = parse_url($url, PHP_URL_HOST);
227	        if ($host !== null && $host !== request()->getHost()) {
228	            return null;
229	        }
230	
231	        // non puntare a sé stessa (la pagina asset): eviterebbe un "indietro" che non torna indietro
232	        if (str_contains((string) parse_url($url, PHP_URL_PATH), '/assets/')) {
233	            return null;
234	        }
235	
236	        return $url;
237	    }
238	
239	    /**
240	     * URL della lista (index) della resource Filament del record, da usare come
241	     * fallback quando manca un Referer valido. null se il record non ha una
242	     * resource registrata nel pannello o l'URL non è risolvibile.
243	     */
244	    private function resourceIndexUrl(): ?string
245	    {
246	        /** @var class-string<\Filament\Resources\Resource>|null $resource */
247	        $resource = \Filament\Facades\Filament::getModelResource($this->resolveOwner());
248	        if ($resource === null) {
249	            return null;
250	        }
251	
252	        try {
253	            $url = $resource::getUrl('index');
254	
255	            return $url ?: null;
256	        } catch (\Throwable) {
257	            return null;
258	        }
259	    }
260	
261	    /**
262	     * Risolve il record proprietario dalla coppia (morph alias, chiave).
263	     * 404 se il tipo non è mappato, il record non esiste o non è OwnsAssets.
264	     *
265	     * @return Model&OwnsAssets
266	     */
267	    public function resolveOwner(): Model
268	    {
269	        if ($this->ownerModel !== null) {
270	            return $this->ownerModel;
271	        }
272	
273	        $class = Relation::getMorphedModel($this->ownerType) ?? $this->ownerType;
274	        abort_unless(class_exists($class), 404);
275	
276	        /** @var class-string<Model> $class */
277	        $record = $class::query()->find($this->ownerKey);
278	        abort_unless($record instanceof OwnsAssets, 404);
279	
280	        return $this->ownerModel = $record;
281	    }
282	
283	    #[Override]
284	    public function getTitle(): string|Htmlable
285	    {
286	        $owner = $this->resolveOwner();
287	        $name = $owner->getAttribute('name');
288	        $key = $owner->getKey();
289	        $label = is_string($name) && $name !== ''
290	            ? $name
291	            : '#' . (is_scalar($key) ? (string) $key : '');
292	
293	        return (string) __('digital-hub::assets.title_for', ['owner' => $label]);
294	    }
295	
296	    /**
297	     * Nessun heading di pagina Filament: il titolo è renderizzato dalla barra del
298	     * finto modal nel blade. Tornando '' (vuoto) il componente di pagina non
299	     * disegna affatto l'header, evitando il doppione.
300	     */
301	    #[Override]
302	    public function getHeading(): string|Htmlable
303	    {
304	        return '';
305	    }
306	
307	    /**
308	     * Tutte le folder del record, caricate una sola volta per request.
309	     *
310	     * @return EloquentCollection<int, AssetFolder>
311	     */
312	    public function allFolders(): EloquentCollection
313	    {
314	        if ($this->folderCache !== null) {
315	            return $this->folderCache;
316	        }
317	
318	        return $this->folderCache = $this->resolveOwner()->allAssetFolders();
319	    }
320	
321	    /**
322	     * Vista ad albero sulle folder del record. Costruita al volo dalla collection
323	     * già cachata per-request ({@see allFolders()}): non tiene stato proprio, così
324	     * l'invalidazione di {@see $folderCache} basta a rifletterne i cambiamenti.
325	     */
326	    private function folderTree(): FolderTree
327	    {
328	        return FolderTree::fromFolders($this->allFolders());
329	    }
330	
331	    /**
332	     * Resolver ownership-scoped per media e folder del record. L'owner non cambia
333	     * nell'arco della request: lo cachiamo una volta (privata, non serializzata
334	     * da Livewire).
335	     */
336	    private function resolver(): OwnedAssetResolver
337	    {
338	        return $this->resolverCache ??= OwnedAssetResolver::for($this->resolveOwner());
339	    }
340	
341	    /**
342	     * Seleziona la folder attiva (null = root). Ignora id non appartenenti al
343	     * record (es. manomissione del payload Livewire).
344	     */
345	    public function selectFolder(?int $folderId): void
346	    {
347	        // cambiando vista la selezione corrente non ha più senso
348	        $this->selectedAssetIds = [];
349	        $this->selectedFolderIds = [];
350	
351	        // aprire una cartella esce dalla modalità "vista piatta filtrata" (14c):
352	        // i filtri sono globali sul record, la navigazione a cartelle no
353	        $this->clearFilters();
354	
355	        if ($folderId === null) {
356	            $this->activeFolderId = null;
357	
358	            return;
359	        }
360	
361	        if ($this->allFolders()->firstWhere('id', $folderId) !== null) {
362	            $this->activeFolderId = $folderId;
363	        }
364	    }
365	
366	    /**
367	     * Svuota la selezione corrente (pulsante "Annulla selezione").
368	     */
369	    public function clearAssetSelection(): void
370	    {
371	        $this->selectedAssetIds = [];
372	        $this->selectedFolderIds = [];
373	    }
374	
375	    /**
376	     * Seleziona tutti gli asset e le sottocartelle attualmente visibili nella
377	     * vista corrente (pulsante "Seleziona tutti", disponibile dopo la prima
378	     * selezione).
379	     */
380	    public function selectAllAssets(): void
381	    {
382	        $this->selectedAssetIds = $this->getAssets()
383	            ->map(function (Media $media): string {
384	                $key = $media->getKey();
385	
386	                return is_int($key) || is_string($key) ? (string) $key : '';
387	            })
388	            ->all();
389	
390	        $this->selectedFolderIds = $this->getSubfolders()
391	            ->map(fn (AssetFolder $folder): string => (string) $folder->id)
392	            ->all();
393	    }
394	
395	    /**
396	     * Sposta un media in una folder (o root) via drag-drop sull'albero (#16b).
397	     * `$mediaId` arriva come stringa dal dataTransfer; `$folderId` null = root.
398	     */
399	    public function moveAssetToFolder(mixed $mediaId, ?int $folderId): void
400	    {
401	        $media = $this->findOwnedMedia($mediaId);
402	        if ($media === null) {
403	            return;
404	        }
405	
406	        if ($folderId !== null && $this->findOwnedFolder($folderId) === null) {
407	            $folderId = null;
408	        }
409	
410	        $media->setAttribute('asset_folder_id', $folderId);
411	        $media->save();
412	
413	        Notification::make()->success()->title(__('digital-hub::assets.asset_moved'))->send();
414	    }
415	
416	    /**
417	     * Riordina un gruppo di folder fratelli via drag-drop nell'albero (#16b).
418	     * Riceve gli id nel nuovo ordine (da SortableJS) e riassegna `sort` per
419	     * posizione. Gli id estranei al record sono ignorati.
420	     *
421	     * @param array<int, int|string> $orderedIds
422	     */
423	    public function reorderFolders(array $orderedIds): void
424	    {
425	        foreach (array_values($orderedIds) as $index => $id) {
426	            $folder = $this->findOwnedFolder($id);
427	            if ($folder === null) {
428	                continue;
429	            }
430	
431	            if ($folder->sort !== $index) {
432	                $folder->sort = $index;
433	                $folder->save();
434	            }
435	        }
436	
437	        $this->folderCache = null;
438	    }
439	
440	    /**
441	     * Albero annidato delle folder del record per il pannello sinistro.
442	     * `children` è ricorsivamente la stessa struttura (non esprimibile come tipo
443	     * ricorsivo preciso in PHPDoc, quindi `mixed`).
444	     *
445	     * @return array<int, array{folder: AssetFolder, children: mixed}>
446	     */
447	    public function getFolderTree(): array
448	    {
449	        return $this->folderTree()->nested();
450	    }
451	
452	    /**
453	     * Sottocartelle dirette della folder attiva, da mostrare come tile nel
454	     * pannello destro insieme ai file. In root ("Home") sono le cartelle di
455	     * primo livello: la root si naviga come una cartella qualunque.
456	     *
457	     * @return \Illuminate\Support\Collection<int, AssetFolder>
458	     */
459	    public function getSubfolders(): \Illuminate\Support\Collection
460	    {
461	        return $this->folderTree()->childrenOf($this->activeFolderId);
462	    }
463	
464	    /**
465	     * Catena dalla root alla folder attiva, per il breadcrumb. Vuota se siamo
466	     * in root. Se l'id attivo non esiste più (folder eliminata), resetta a root.
467	     *
468	     * @return list<AssetFolder>
469	     */
470	    public function getBreadcrumbTrail(): array
471	    {
472	        if ($this->activeFolderId === null) {
473	            return [];
474	        }
475	
476	        $trail = $this->folderTree()->breadcrumb($this->activeFolderId);
477	        if ($trail === null) {
478	            // folder eliminata sotto i piedi: torna a root
479	            $this->activeFolderId = null;
480	
481	            return [];
482	        }
483	
484	        return $trail;
485	    }
486	
487	    /**
488	     * Media mostrati nel pannello destro: i soli media diretti della folder
489	     * attiva. In root ("Home") sono i file caricati direttamente in root
490	     * (nessuna folder assegnata), come in una cartella qualunque.
491	     *
492	     * @return \Illuminate\Support\Collection<int, \Spatie\MediaLibrary\MediaCollections\Models\Media>
493	     */
494	    public function getAssets(): \Illuminate\Support\Collection
495	    {
496	        // con filtri attivi (14c) la vista è "piatta": tutti i file del record
497	        // che corrispondono, a prescindere dalla cartella.
498	        if ($this->hasActiveFilters()) {
499	            return $this->filter()->apply();
500	        }
501	
502	        $folder = $this->activeFolderId !== null
503	            ? $this->findOwnedFolder($this->activeFolderId)
504	            : null;
505	
506	        return $this->resolveOwner()->assetsInFolder($folder);
507	    }
508	
509	    // -- Filtri asset (14c) --------------------------------------------------
510	
511	    /**
512	     * Vista sui filtri (stato attivo, applicazione, etichette, opzioni),
513	     * costruita al volo dai valori grezzi dei filtri (proprietà pubbliche legate
514	     * ai controlli) e dalla collection già cachata di tutti i media del record
515	     * ({@see recordAssets()}). La logica vive in {@see AssetFilter}: qui c'è solo
516	     * il cablaggio, così i valori restano sul componente (wire:model) ma il calcolo
517	     * è testabile in isolamento.
518	     */
519	    private function filter(): AssetFilter
520	    {
521	        return AssetFilter::make(
522	            $this->recordAssets(),
523	            $this->filterType,
524	            $this->filterUploadedBy,
525	            $this->filterUploadedFrom,
526	            $this->filterUploadedTo,
527	            $this->filterMinSizeMb,
528	            $this->filterMaxSizeMb,
529	        );
530	    }
531	
532	    /**
533	     * True se almeno un filtro è impostato: sblocca la vista piatta filtrata e
534	     * fa comparire il link "azzera filtri".
535	     */
536	    public function hasActiveFilters(): bool
537	    {
538	        return $this->filter()->isActive();
539	    }
540	
541	    /**
542	     * Id di cartella da evidenziare nella sidebar sinistra. In modalità filtrata
543	     * (14c) la vista è piatta e cross-cartella: momentaneamente NESSUNA voce
544	     * dev'essere attiva (né "Home" né una cartella), quindi si ritorna un
545	     * sentinella che non corrisponde a nulla (-1, gli id reali sono positivi).
546	     * Fuori dai filtri è la cartella attiva ({@see $activeFolderId}), con null =
547	     * "Home". Non tocca la navigazione: `selectFolder` continua a usare l'id reale.
548	     */
549	    public function sidebarActiveFolderId(): ?int
550	    {
551	        return $this->hasActiveFilters() ? -1 : $this->activeFolderId;
552	    }
553	
554	    /**
555	     * Azzera tutti i filtri (link "azzera" e ingresso in navigazione cartelle).
556	     */
557	    public function clearFilters(): void
558	    {
559	        $this->filterType = null;
560	        $this->filterUploadedBy = null;
561	        $this->filterUploadedFrom = null;
562	        $this->filterUploadedTo = null;
563	        $this->filterMinSizeMb = null;
564	        $this->filterMaxSizeMb = null;
565	    }
566	
567	    /**
568	     * Estremo superiore dello slider "dimensioni" (14c): il peso, in MB, del più
569	     * grande asset del record. 0 se il record è senza asset.
570	     */
571	    public function sizeFilterMaxMb(): float
572	    {
573	        return $this->filter()->sizeMaxMb();
574	    }
575	
576	    /**
577	     * Il filtro dimensioni è attivo solo se un estremo restringe davvero: peso
578	     * minimo > 0 oppure peso massimo sotto il file più grande.
579	     */
580	    public function sizeFilterActive(): bool
581	    {
582	        return $this->filter()->sizeIsActive();
583	    }
584	
585	    /**
586	     * Imposta l'intervallo peso (MB) in un colpo solo: chiamato dallo slider
587	     * doppio via un unico $wire, così i due estremi arrivano nello stesso payload
588	     * e non si disallineano con azioni rapide (min ed max erano prima due set
589	     * separati, uno differito).
590	     */
591	    public function setSizeRange(float $min, float $max): void
592	    {
593	        // difesa: normalizza un eventuale ordine invertito
594	        $this->filterMinSizeMb = min($min, $max);
595	        $this->filterMaxSizeMb = max($min, $max);
596	    }
