1012	    /**
1013	     * Carica uno o più file nella folder attiva (root se nessuna selezionata).
1014	     * I file finiscono nella collection asset del record (disco scoped).
1015	     */
1016	    public function uploadAssetsAction(): Action
1017	    {
1018	        return Action::make('uploadAssets')
1019	            ->label(__('digital-hub::assets.upload'))
1020	            ->icon(Heroicon::OutlinedArrowUpTray)
1021	            ->modalHeading(__('digital-hub::assets.upload_heading'))
1022	            ->schema([
1023	                FileUpload::make('files')
1024	                    ->label(__('digital-hub::assets.files_field'))
1025	                    ->multiple()
1026	                    ->required()
1027	                    ->storeFiles(false),
1028	            ])
1029	            ->action(function (array $data): void {
1030	                $owner = $this->resolveOwner();
1031	                $files = $data['files'] ?? [];
1032	                if (! is_array($files)) {
1033	                    return;
1034	                }
1035	
1036	                $count = 0;
1037	                foreach ($files as $file) {
1038	                    if (! $file instanceof TemporaryUploadedFile) {
1039	                        continue;
1040	                    }
1041	
1042	                    $media = $owner->addMedia($file)
1043	                        ->usingName(pathinfo($file->getClientOriginalName(), PATHINFO_FILENAME))
1044	                        ->toMediaCollection($owner->assetsCollection());
1045	                    $media->setAttribute('asset_folder_id', $this->activeFolderId);
1046	
1047	                    // autore: FK nullable verso l'utente + snapshot del nome (fallback
1048	                    // se l'utente verrà eliminato → uploaded_by_id null per nullOnDelete)
1049	                    /** @disregard P1013 */
1050	                    $user = auth()->user();
1051	                    $media->setAttribute('uploaded_by_id', $user?->getAuthIdentifier());
1052	                    $media->setAttribute('uploaded_by_name', $user instanceof Model ? $user->getAttribute('name') : null);
1053	
1054	                    // l'elaborazione (metadati, dimensioni, future taglie) la fa un
1055	                    // job in coda: il media entra "pending" finché il job non lo chiude
1056	                    $media->setAttribute('processing_status', AssetProcessingStatus::Pending->value);
1057	                    $media->save();
1058	
1059	                    $this->dispatchProcessing($media);
1060	                    $count++;
1061	                }
1062	
1063	                if ($count > 0) {
1064	                    Notification::make()
1065	                        ->success()
1066	                        ->title(trans_choice('digital-hub::assets.assets_uploaded', $count, ['count' => $count]))
1067	                        ->send();
1068	                }
1069	            });
1070	    }
