1408	    /**
1409	     * Media su cui operano scarica/condividi/sposta/elimina: dal menu contestuale
1410	     * arriva il singolo `media` (id) o la singola `folder` (id, espansa nei media
1411	     * del suo sottoalbero) come argument, dalla barra multipla si usa la selezione
1412	     * corrente ($selectedAssetIds + $selectedFolderIds, cartelle espanse). Filtra
1413	     * gli id non appartenenti al record e deduplica (un file può essere selezionato
1414	     * sia direttamente sia dentro una cartella selezionata). È il punto in cui
1415	     * azioni singole e di gruppo condividono il target.
1416	     *
1417	     * @param array<array-key, mixed> $arguments
1418	     * @return list<Media>
1419	     */
1420	    private function actionMedia(array $arguments): array
1421	    {
1422	        if (array_key_exists('media', $arguments)) {
1423	            $item = $this->findOwnedMedia($arguments['media']);
1424	
1425	            return $item === null ? [] : [$item];
1426	        }
1427	
1428	        if (array_key_exists('folder', $arguments)) {
1429	            $folder = $this->findOwnedFolder($arguments['folder']);
1430	
1431	            return $folder === null ? [] : $this->subtreeMedia([$folder]);
1432	        }
1433	
1434	        // selezione mista: file spuntati + contenuto delle cartelle spuntate
1435	        $byKey = [];
1436	        foreach ($this->selectedAssetIds as $id) {
1437	            $item = $this->findOwnedMedia($id);
1438	            $key = $item?->getKey();
1439	            if ($item !== null && (is_int($key) || is_string($key))) {
1440	                $byKey[(string) $key] = $item;
1441	            }
1442	        }
1443	
1444	        $folders = [];
1445	        foreach ($this->selectedFolderIds as $id) {

1446	            $folder = $this->findOwnedFolder($id);
1447	            if ($folder !== null) {
1448	                $folders[] = $folder;
1449	            }
1450	        }
1451	        foreach ($this->subtreeMedia($folders) as $item) {
1452	            $key = $item->getKey();
1453	            if (is_int($key) || is_string($key)) {
1454	                $byKey[(string) $key] = $item;
1455	            }
1456	        }
1457	
1458	        return array_values($byKey);
1459	    }
