1562	    private function createPersistentShare(array $media, array $data): void
1563	    {
1564	        if ($media === []) {
1565	            // es. cartella selezionata/condivisa ma vuota: avvisa invece di creare uno share vuoto
1566	            Notification::make()->warning()->title(__('digital-hub::assets.nothing_to_share'))->send();
1567	
