1570	
1571	        // la scadenza è a granularità giorno: vale fino a fine giornata
1572	        $expiresAt = is_string($data['expires_at'] ?? null) && $data['expires_at'] !== ''
1573	            ? \Illuminate\Support\Carbon::parse($data['expires_at'])->endOfDay()
1574	            : null;
1575	
1576	        $share = AssetShare::createPersistent(
1577	            $media,
1578	            is_string($data['name'] ?? null) ? $data['name'] : null,
1579	            is_string($data['password'] ?? null) ? $data['password'] : null,
1580	            $expiresAt,
1581	            auth()->id(),
